<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
require __DIR__.'/readiness_lib.php';
$uid=auth();$error='';$saved=false;
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();
 try {
  $batchId=(int)($_POST['batch_id']??0);$batch=row_owned('dough_batches',$batchId);
  $containerId=($_POST['container_id']??'')===''?null:(int)$_POST['container_id'];
  if($containerId!==null && !query('SELECT id FROM batch_containers WHERE id=? AND batch_id=?',[$containerId,$batchId])->fetch())throw new RuntimeException('Container does not belong to the batch.');
  $tmp=($_POST['dough_temp_f']??'')===''?null:number($_POST['dough_temp_f'],0,150,'dough temperature');
  $rise=($_POST['rise_score']??'')===''?null:(int)number($_POST['rise_score'],1,5,'rise score');
  $handling=(string)($_POST['handling']??'unknown');if(!in_array($handling,['unknown','tight','balanced','slack','sticky','tearing'],true))throw new RuntimeException('Invalid handling category.');
  query('INSERT INTO dough_readiness_checks (batch_id,container_id,observed_at,dough_temp_f,rise_score,handling,notes,recorded_by_user_id) VALUES (?,?,NOW(),?,?,?,?,?)',[$batchId,$containerId,$tmp,$rise,$handling,plain($_POST['notes']??'',1500),$uid]);
  header('Location: readiness.php?batch_id='.$batchId.'&saved=1');exit;
 }catch(Throwable $ex){$error=$ex->getMessage();}
}
$batches=query('SELECT b.id,b.batch_code,b.balled_at,b.process_steps_snapshot,b.recipe_id,r.name recipe_name FROM dough_batches b JOIN recipes r ON b.recipe_id=r.id ORDER BY b.created_at DESC LIMIT 250')->fetchAll();
$id=(int)($_GET['batch_id']??($batches[0]['id']??0));$batch=null;
foreach($batches as $b){if((int)$b['id']===$id){$batch=$b;break;}}
$containers=$batch?query('SELECT id,container_code,label FROM batch_containers WHERE batch_id=? ORDER BY id',[$id])->fetchAll():[];
$checks=$batch?query('SELECT c.*,u.display_name,bc.container_code FROM dough_readiness_checks c JOIN users u ON u.id=c.recorded_by_user_id LEFT JOIN batch_containers bc ON bc.id=c.container_id WHERE c.batch_id=? ORDER BY c.observed_at DESC,c.id DESC LIMIT 90',[$id])->fetchAll():[];
$assessment=$batch?lab_readiness_assess($batch,$checks):null;
function h(string $x):string{return htmlspecialchars($x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Dough Readiness · Pizza Lab</title><link rel="stylesheet" href="assets/style.css?v=1.5.5"></head><body><main class="view" style="max-width:1060px"><p><a href="index.php">← Pizza Lab</a></p><header class="section-head"><div><h1>Dough Readiness</h1><p>Actual dough observations, by batch and proofing container. Readiness is advisory, not a measurement of gluten strength.</p></div></header><?php if($error):?><div class="danger"><?=h($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="notice-strip">Readiness observation saved.</div><?php endif;?><form method="get" class="panel mb"><label>Choose batch<select name="batch_id" onchange="this.form.submit()"><option value="">Select a batch</option><?php foreach($batches as $b):?><option value="<?=$b['id']?>" <?=$id===$b['id']?'selected':''?>><?=h($b['batch_code'].' · '.$b['recipe_name'])?></option><?php endforeach;?></select></label><noscript><button>Load batch</button></noscript></form><?php if($batch):?><div class="grid-2"><section class="panel"><h2>Readiness estimate</h2><p><strong><?=h($assessment['status'])?></strong></p><p>Hours since balling: <?=h((string)($assessment['hours_since_balling']??'Not recorded'))?> · Planned cold-ball hours: <?=h((string)($assessment['target_ball_hours']??'Not recorded'))?></p><p>Evidence confidence: <?=h($assessment['evidence_confidence'])?></p><?php foreach($assessment['cautions'] as $c):?><p class="small">• <?=h($c)?></p><?php endforeach;?><p class="hint"><?=h($assessment['recommendation'])?></p></section><form method="post" class="panel stack"><h2>Record dough check</h2><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="batch_id" value="<?=$id?>"><label>Proofing container (optional)<select name="container_id"><option value="">Whole batch / unknown</option><?php foreach($containers as $c):?><option value="<?=$c['id']?>"><?=h($c['container_code'].' '.$c['label'])?></option><?php endforeach;?></select></label><div class="two"><label>Dough temperature °F (optional)<input type="number" name="dough_temp_f" step=".1" min="0" max="150"></label><label>Visual rise (1–5, optional)<select name="rise_score"><option value="">Not recorded</option><?php for($i=1;$i<=5;$i++):?><option value="<?=$i?>"><?=$i?></option><?php endfor;?></select></label></div><label>Handling<select name="handling"><?php foreach(['unknown','tight','balanced','slack','sticky','tearing'] as $s):?><option value="<?=$s?>"><?=ucfirst($s)?></option><?php endforeach;?></select></label><label>Notes<textarea name="notes" maxlength="1500" placeholder="Stretch, gas retention, expansion, smell, stickiness…"></textarea></label><button class="primary">Save actual observation</button></form></div><section class="panel mt"><h2>Historical readings</h2><table class="compact-table"><thead><tr><th>Observed</th><th>Container</th><th>°F</th><th>Rise</th><th>Handling</th><th>Recorded by</th></tr></thead><tbody><?php foreach($checks as $c):?><tr><td><?=h($c['observed_at'])?></td><td><?=h($c['container_code']??'Whole batch')?></td><td><?=h((string)($c['dough_temp_f']??'—'))?></td><td><?=h((string)($c['rise_score']??'—'))?></td><td><?=h($c['handling'])?></td><td><?=h($c['display_name'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$checks):?><p class="muted">No observations yet.</p><?php endif;?></section><?php endif;?></main></body></html>
